import { StatusBar } from 'expo-status-bar';
import { StyleSheet, Text, View, TouchableOpacity } from 'react-native';
import { useState } from 'react';

export default function App() {
    const [role, setRole] = useState(null);

    const renderHome = () => (
        <View style={styles.menuContainer}>
            <Text style={styles.title}>Kaizen Transport</Text>
            <Text style={styles.subtitle}>Selecciona tu perfil:</Text>

            <TouchableOpacity style={[styles.button, { backgroundColor: '#2c3e50' }]} onPress={() => setRole('ADMIN')}>
                <Text style={styles.buttonText}>Administrador</Text>
            </TouchableOpacity>

            <TouchableOpacity style={[styles.button, { backgroundColor: '#27ae60' }]} onPress={() => setRole('CHOFER')}>
                <Text style={styles.buttonText}>Chofer</Text>
            </TouchableOpacity>

            <TouchableOpacity style={[styles.button, { backgroundColor: '#2980b9' }]} onPress={() => setRole('USUARIO')}>
                <Text style={styles.buttonText}>Paciente / Usuario</Text>
            </TouchableOpacity>
        </View>
    );

    const renderRoleScreen = () => (
        <View style={styles.roleContainer}>
            <Text style={styles.roleTitle}>Modo: {role}</Text>
            <TouchableOpacity style={styles.backButton} onPress={() => setRole(null)}>
                <Text style={styles.backButtonText}>Volver</Text>
            </TouchableOpacity>
        </View>
    );

    return (
        <View style={styles.container}>
            {role ? renderRoleScreen() : renderHome()}
            <StatusBar style="auto" />
        </View>
    );
}

const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: '#f5f6fa',
        alignItems: 'center',
        justifyContent: 'center',
    },
    menuContainer: {
        width: '100%',
        alignItems: 'center',
        padding: 20,
    },
    title: {
        fontSize: 28,
        fontWeight: 'bold',
        marginBottom: 10,
        color: '#333',
    },
    subtitle: {
        fontSize: 18,
        marginBottom: 30,
        color: '#666',
    },
    button: {
        width: '80%',
        padding: 20,
        borderRadius: 15,
        marginBottom: 15,
        alignItems: 'center',
        shadowColor: "#000",
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.25,
        shadowRadius: 3.84,
        elevation: 5,
    },
    buttonText: {
        color: '#fff',
        fontSize: 18,
        fontWeight: '600',
    },
    roleContainer: {
        alignItems: 'center',
    },
    roleTitle: {
        fontSize: 24,
        fontWeight: 'bold',
        marginBottom: 20,
    },
    backButton: {
        padding: 10,
    },
    backButtonText: {
        color: '#e74c3c',
        fontSize: 16,
    }
});
